  { dia: 18, categoria: "UNA CANCIÓN, UN RECUERDO", youtubeId: "2cuDp5ENoao", cancionTitulo: "KEEPER", cancionArtista: "GIVĒON", inspiracionCancion: "Canciones que despiertan recuerdos y emociones.", palabraNueva: { palabra: "Nostalgia", significado: "Cariño o emoción al recordar una época, una persona o una experiencia." }, cartas: {
    buenosDias: { titulo: "¿Qué canción te lleva lejos?", contenido: "Buenos días. Hay canciones que empiezan a sonar y, sin pedir permiso, nos devuelven a una época completa. Ojalá hoy aparezca una de esas que te hacen sonreír." },
    mensajePrincipal: { titulo: "El recuerdo detrás de una canción", contenido: "Elige una canción que te recuerde a una etapa de tu vida. Puede ser de tu infancia, de una salida, de una amistad o de un momento que ya pasó. Si te apetece, compártela con alguien y cuéntale en una frase qué recuerdo trae. También puedes guardarla para ti; no todos los recuerdos necesitan explicación." },
    palabraNueva: { titulo: "Nostalgia", contenido: "La nostalgia puede ser dulce o un poco melancólica. No siempre significa querer volver atrás; a veces solo agradecemos que algo haya formado parte de nuestra historia." },
    buenasNoches: { titulo: "Una melodía para cerrar", contenido: "Quizá hoy una canción te devolvió una imagen que tenías guardada. Quédate con lo bonito y deja que la noche siga tranquila. Descansa." }
  }},
  { dia: 19, categoria: "¿QUÉ PREFIERES?", youtubeId: "azjOefV3jik", cancionTitulo: "Wandering Romance", cancionArtista: "Jorja Smith", inspiracionCancion: "Un ambiente ligero para inventar reglas y probar ideas.", palabraNueva: { palabra: "Dilema", significado: "Una elección entre dos posibilidades que obliga a pensar qué prefieres." }, cartas: {
    buenosDias: { titulo: "Dos opciones y ninguna respuesta correcta", contenido: "Buenos días. Hoy toca un juego pequeño, de esos que empiezan con una pregunta y terminan revelando gustos inesperados." },
    mensajePrincipal: { titulo: "Tres dilemas rápidos", contenido: "Si te apetece jugar con alguien, respondan sin pensarlo demasiado: ¿viaje a la playa o a la montaña?, ¿poder pausar el tiempo o volver diez segundos atrás?, ¿comedia absurda o misterio que te haga sospechar de todos? Pueden inventar una cuarta pregunta. Se juega en cinco minutos y también funciona por mensajes; si hoy prefieres estar a tu aire, elige tus respuestas mentalmente." },
    palabraNueva: { titulo: "Dilema", contenido: "Un dilema presenta dos caminos y nos invita a elegir. En este juego no se busca la respuesta correcta, sino descubrir qué piensa cada quien." },
    buenasNoches: { titulo: "La elección puede cambiar mañana", contenido: "A veces uno elige playa y al día siguiente montaña. Está permitido cambiar de opinión. Que descanses." }
  }},
  { dia: 20, categoria: "CHOCOLATE Y UN GUSTO PERSONAL", youtubeId: "yQJjN0Kd5EI", cancionTitulo: "DON'T LEAVE", cancionArtista: "GIVĒON", inspiracionCancion: "Una pausa sensorial para descubrir aromas y texturas.", palabraNueva: { palabra: "Matiz", significado: "Un pequeño detalle que diferencia un sabor, una sensación o una idea de otra." }, cartas: {
    buenosDias: { titulo: "Un gusto que no necesita ceremonia", contenido: "Buenos días. Hay pequeños gustos que mejoran una tarde sin necesitar una ocasión especial. A veces basta con un cuadrito de chocolate y un momento tranquilo." },
    mensajePrincipal: { titulo: "¿Qué chocolate va contigo?", contenido: "Si tienes chocolate amargo que sea seguro para ti, disfruta un trocito cuando te provoque. ¿Te gusta más intenso y seco, o con un toque dulce? Si no tienes, piensa en tu favorito y guárdalo como próxima compra. Revisa siempre el etiquetado por la alergia al maní y las advertencias de trazas; si hay duda sobre ingredientes o contaminación cruzada, no lo consumas." },
    palabraNueva: { titulo: "Matiz", contenido: "Un matiz es ese detalle pequeño que cambia la experiencia. En el chocolate puede ser la intensidad, la textura o una nota de sabor que aparece al final." },
    buenasNoches: { titulo: "Un gusto pequeño también alegra", contenido: "Ojalá hoy hayas tenido un momento para disfrutar algo que te gusta. No hace falta convertir cada antojo en un evento. Buenas noches." }
  }},
  { dia: 21, categoria: "LOS DETALLES QUE SÍ SE NOTAN", youtubeId: "iXPygS94LME", cancionTitulo: "On Your Own", cancionArtista: "Jorja Smith", inspiracionCancion: "Una canción para acompañar una jornada de apoyo mutuo.", palabraNueva: { palabra: "Reciprocidad", significado: "Una relación equilibrada en la que el interés y el cuidado pueden darse y recibirse." }, cartas: {
    buenosDias: { titulo: "Un gesto sencillo", contenido: "Buenos días. A veces alguien nos alegra la jornada con algo mínimo: recordar una canción, preguntar cómo nos fue o mandar un mensaje justo a tiempo. Que hoy no te falten esos detalles." },
    mensajePrincipal: { titulo: "El detalle que te alegra el día", contenido: "Piensa en un gesto pequeño que te haga sentir acompañado: que te compartan una canción, que recuerden algo que contaste, que te hagan reír o que respeten tu espacio. Si quieres, puedes decírselo a alguien en una frase. No hay listas que cumplir ni favores que devolver; solo reconocer qué cosas te hacen bien." },
    palabraNueva: { titulo: "Reciprocidad", contenido: "No es llevar una cuenta de quién hizo más. Es que el interés y el cuidado puedan circular con naturalidad, respetando los tiempos y las necesidades de cada persona." },
    buenasNoches: { titulo: "Que los detalles sean libres", contenido: "Ojalá recibas cariño sin sentir que tienes que ganártelo ni devolverlo de inmediato. Los gestos más bonitos nacen de las ganas, no de una obligación. Descansa." }
  }}

